const body = $input.first().json;
if (!body.resume_text) throw new Error('resume_text is required');
return [{ json: {
  resume_text: body.resume_text,
  candidate_id: body.candidate_id || `cand_${Date.now()}`,
  prompt: `You are an AI Recruitment Orchestrator. Process this job application by using the available tools in this order:
1. extract_resume — to parse the resume
2. analyze_skills — to analyze extracted data
3. find_job_matches — to find matching jobs
4. screen_candidate — to screen based on matches
5. generate_recommendation — to produce final hiring decision

Resume Text:
${body.resume_text.substring(0, 3000)}

After using all tools, summarize the complete recruitment assessment as a final JSON report.`
} }];

// TOOL: Resume Extractor
const resumeText = $input.first().json.query || '';

// Build structured extraction prompt
const systemPrompt = 'Extract resume. Return ONLY JSON: {"personal_info":{"name":"","email":"","phone":"","location":""},"education":[{"institution":"","level":"","field":"","year":""}],"experience":[{"company":"","role":"","duration":"","responsibilities":[]}],"technical_skills":[],"certifications":[]}';

let extracted = {};
try {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.studio.nebius.ai/v1/chat/completions',
    headers: { 'Authorization': 'Bearer YOUR_NEBIUS_API_KEY', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'google/gemma-2-9b-it-fast', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: resumeText.substring(0, 4000) }], temperature: 0.3 })
  });
  const result = JSON.parse(response);
  const raw = result.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  extracted = JSON.parse(m ? m[1] : cleaned);
} catch(e) { extracted = { error: e.message }; }

return [{ json: { extracted_profile: extracted, tool: 'extract_resume', status: extracted.error ? 'failed' : 'success' } }];

// TOOL: Skills Analyzer
const input = $input.first().json.query || '';

const systemPrompt = 'Analyze this candidate profile. Rules: Junior < 3yr, Mid 3-7yr, Senior > 7yr. Return ONLY JSON: {"technical_skills":[],"years_of_experience":0,"education":{"level":"","field":""},"experience_level":"Junior|Mid-level|Senior","key_achievements":[],"domain_expertise":[]}';

let analysis = {};
try {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.studio.nebius.ai/v1/chat/completions',
    headers: { 'Authorization': 'Bearer YOUR_NEBIUS_API_KEY', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'google/gemma-2-9b-it-fast', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: input }], temperature: 0.3 })
  });
  const result = JSON.parse(response);
  const raw = result.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  analysis = JSON.parse(m ? m[1] : cleaned);
} catch(e) { analysis = { error: e.message, technical_skills: [], experience_level: 'Junior' }; }

return [{ json: { skills_analysis: analysis, tool: 'analyze_skills', status: analysis.error ? 'failed' : 'success' } }];

// TOOL: Job Matcher & Market Intelligence
const input = $input.first().json.query || '';

const systemPrompt = 'You are a Market Intelligence Expert. Generate 3 realistic 2026 job listings matching this candidate. Return ONLY JSON: {"matched_jobs":[{"title":"","company":"","location":"","salary_range":"","match_score":85,"requirements":[],"source":"Live Market 🌐"}]}';

let jobMatches = {};
try {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.studio.nebius.ai/v1/chat/completions',
    headers: { 'Authorization': 'Bearer YOUR_NEBIUS_API_KEY', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'google/gemma-2-9b-it-fast', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: input }], temperature: 0.6 })
  });
  const result = JSON.parse(response);
  const raw = result.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  jobMatches = JSON.parse(m ? m[1] : cleaned);
} catch(e) { jobMatches = { matched_jobs: [], error: e.message }; }

return [{ json: { job_matches: jobMatches, tool: 'find_job_matches', status: jobMatches.error ? 'failed' : 'success' } }];

// TOOL: Candidate Screener
const input = $input.first().json.query || '';

const systemPrompt = 'You are a senior HR Screener. Evaluate this candidate against the job matches. Return ONLY JSON: {"screening_report":"3-4 sentence detailed assessment","screening_score":75,"red_flags":["flag1"]}';

let screening = {};
try {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.studio.nebius.ai/v1/chat/completions',
    headers: { 'Authorization': 'Bearer YOUR_NEBIUS_API_KEY', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'google/gemma-2-9b-it-fast', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: input }], temperature: 0.4 })
  });
  const result = JSON.parse(response);
  const raw = result.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  screening = JSON.parse(m ? m[1] : cleaned);
} catch(e) { screening = { screening_report: 'Error', screening_score: 50, red_flags: [] }; }

return [{ json: { screening_results: screening, tool: 'screen_candidate', status: 'success' } }];

// TOOL: Final Recommender
const input = $input.first().json.query || '';

const systemPrompt = 'You are a Senior HR Director. Generate a final hiring recommendation. Return ONLY JSON: {"hiring_status":"Recommended|Not Recommended|Pending Review","recommendation":"2-3 professional sentences","next_steps":["step1","step2"],"confidence_level":"Low|Medium|High"}';

let recommendation = {};
try {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.studio.nebius.ai/v1/chat/completions',
    headers: { 'Authorization': 'Bearer YOUR_NEBIUS_API_KEY', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'google/gemma-2-9b-it-fast', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: input }], temperature: 0.5 })
  });
  const result = JSON.parse(response);
  const raw = result.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  recommendation = JSON.parse(m ? m[1] : cleaned);
} catch(e) { recommendation = { hiring_status: 'Pending Review', recommendation: 'Manual review required.', next_steps: [], confidence_level: 'Low' }; }

return [{ json: { final_recommendation: recommendation, tool: 'generate_recommendation', status: 'success' } }];

const agentOutput = $input.first().json.output || 'No output';
